namespace Fdg.Generator.Emit;

/// <summary>The "generated, do not edit" marker written at the top of every generated file that allows comments.</summary>
internal static class Header
{
    public const string Text = "<auto-generated> by fdg-gen from rules/*.yaml — do not edit";

    public const string CSharp = "// " + Text;

    public const string GlobalConfig = "# " + Text;

    public const string Markdown = "<!-- " + Text + " -->";
}
